mapper.sql:
handle.tenant_id = #{tenantId} AND handle.deleted_at IS NULL
AND handle.label_id = #{query.labelId}
AND COALESCE(current_group.folder_id, handle.folder_id) = #{query.folderId}
AND COALESCE(current_group.folder_id, handle.folder_id) IS NULL
AND handle.is_historical = 1
AND handle.is_post_control = 1
AND handle.is_historical = 1 AND handle.is_post_control = 1
AND EXISTS ( SELECT 1 FROM wa_account_group_binding binding INNER JOIN wa_group_participant participant ON participant.tenant_id = binding.tenant_id AND participant.group_id = binding.group_id AND participant.id = binding.participant_id INNER JOIN account execution_account ON execution_account.tenant_id = binding.tenant_id AND execution_account.id = binding.account_id AND execution_account.deleted_at IS NULL AND execution_account.protocol_account_id IS NOT NULL AND TRIM(execution_account.protocol_account_id) <> '' INNER JOIN account_state execution_state ON execution_state.tenant_id = execution_account.tenant_id AND execution_state.account_id = execution_account.id AND execution_state.login_state = 1 AND execution_state.account_state = 2 WHERE binding.tenant_id = handle.tenant_id AND binding.group_id = current_group.id AND participant.presence_status = 1 AND participant.role IN (2, 3) )
AND NOT EXISTS ( SELECT 1 FROM wa_account_group_binding binding INNER JOIN wa_group_participant participant ON participant.tenant_id = binding.tenant_id AND participant.group_id = binding.group_id AND participant.id = binding.participant_id INNER JOIN account execution_account ON execution_account.tenant_id = binding.tenant_id AND execution_account.id = binding.account_id AND execution_account.deleted_at IS NULL AND execution_account.protocol_account_id IS NOT NULL AND TRIM(execution_account.protocol_account_id) <> '' INNER JOIN account_state execution_state ON execution_state.tenant_id = execution_account.tenant_id AND execution_state.account_id = execution_account.id AND execution_state.login_state = 1 AND execution_state.account_state = 2 WHERE binding.tenant_id = handle.tenant_id AND binding.group_id = current_group.id AND participant.presence_status = 1 AND participant.role IN (2, 3) )
AND COALESCE( current_invite.checked_member_count, input_invite.checked_member_count, current_profile.member_count ) IS NOT NULL AND COALESCE( current_invite.checked_member_count, input_invite.checked_member_count, current_profile.member_count ) >= #{query.memberCountMin}
AND COALESCE( current_invite.checked_member_count, input_invite.checked_member_count, current_profile.member_count ) IS NOT NULL AND COALESCE( current_invite.checked_member_count, input_invite.checked_member_count, current_profile.member_count ) <= #{query.memberCountMax}
AND EXISTS ( SELECT 1 FROM wa_group_participant owner WHERE owner.tenant_id = current_group.tenant_id AND owner.group_id = current_group.id AND owner.role = 3 AND owner.phone_country_iso2 = #{query.countryIso2} )
AND EXISTS ( SELECT 1 FROM wa_group_participant owner INNER JOIN country owner_country ON owner_country.iso2 = owner.phone_country_iso2 AND owner_country.deleted_at IS NULL WHERE owner.tenant_id = current_group.tenant_id AND owner.group_id = current_group.id AND owner.role = 3 AND owner_country.continent_code = #{query.continentCode} )
AND current_profile.wa_created_at IS NOT NULL AND current_profile.wa_created_at > 0 AND current_profile.wa_created_at <= #{query.nowSeconds} * 1000
AND FLOOR( (#{query.nowSeconds} - FLOOR(current_profile.wa_created_at / 1000)) / 86400 ) >= #{query.ageDaysMin}
AND FLOOR( (#{query.nowSeconds} - FLOOR(current_profile.wa_created_at / 1000)) / 86400 ) <= #{query.ageDaysMax}
AND source_batch.source_file_name LIKE CONCAT('%', #{query.sourceFileName}, '%')
AND handle.origin = #{query.origin}
AND handle.membership_state = #{query.membershipState}
AND COALESCE(current_invite.health_status, input_invite.health_status) IS NULL AND COALESCE(current_invite.banned, input_invite.banned, 0) = 0
AND COALESCE(current_invite.health_status, input_invite.health_status) = 1 AND COALESCE(current_invite.banned, input_invite.banned, 0) = 0
AND COALESCE(current_invite.banned, input_invite.banned, 0) = 1
AND COALESCE(current_invite.health_status, input_invite.health_status) = 2 AND COALESCE(current_invite.banned, input_invite.banned, 0) = 0
AND COALESCE(current_invite.health_status, input_invite.health_status) = 3 AND COALESCE(current_invite.banned, input_invite.banned, 0) = 0
AND ( COALESCE( NULLIF(TRIM(current_group.display_name), ''), NULLIF(TRIM(input_invite.display_name), ''), current_profile.subject, input_invite.preview_subject ) LIKE CONCAT('%', #{query.keyword}, '%') OR COALESCE(current_profile.subject, input_invite.preview_subject) LIKE CONCAT('%', #{query.keyword}, '%') OR handle.link_url LIKE CONCAT('%', #{query.keyword}, '%') OR COALESCE(current_invite.invite_code, input_invite.invite_code) LIKE CONCAT('%', #{query.keyword}, '%') OR current_group.group_jid LIKE CONCAT('%', #{query.keyword}, '%') OR EXISTS ( SELECT 1 FROM wa_group_participant owner WHERE owner.tenant_id = current_group.tenant_id AND owner.group_id = current_group.id AND owner.role = 3 AND owner.phone LIKE CONCAT('%', #{query.keyword}, '%') ) OR EXISTS ( SELECT 1 FROM wa_group_participant participant INNER JOIN account controlled_account ON controlled_account.tenant_id = participant.tenant_id AND controlled_account.ws_phone = participant.phone AND controlled_account.deleted_at IS NULL WHERE participant.tenant_id = current_group.tenant_id AND participant.group_id = current_group.id AND participant.presence_status = 1 AND participant.role IN (2, 3) AND participant.phone LIKE CONCAT('%', #{query.keyword}, '%') ) )
